using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer;

/// <summary>
/// MCP tools that call an external API via HttpClient.
/// </summary>
public class ApiTools(IHttpClientFactory httpClientFactory)
{
    [McpServerTool, Description("Fetches data from the external API for a given resource ID.")]
    public async Task<string> FetchResource(
        [Description("The unique identifier of the resource to fetch")] string resourceId,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");

        var response = await client.GetAsync($"resources/{resourceId}", cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        return json;
    }

    [McpServerTool, Description("Searches the external API with a query string.")]
    public async Task<string> SearchApi(
        [Description("The search query")] string query,
        [Description("Maximum number of results to return (default: 10)")] int maxResults = 10,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");

        var response = await client.GetAsync($"search?q={Uri.EscapeDataString(query)}&limit={maxResults}", cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        return json;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpServer;

/// <summary>
/// MCP prompt templates for summarization tasks.
/// </summary>
public class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a concise summary of the provided text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text content to summarize")] string content,
        [Description("Desired summary style: brief, detailed, or bullet-points")] string style = "brief")
    {
        var systemInstruction = style switch
        {
            "detailed" => "Provide a thorough summary covering all key points, context, and conclusions.",
            "bullet-points" => "Summarize the content as a concise list of bullet points highlighting the main ideas.",
            _ => "Provide a brief, one-paragraph summary capturing the essential meaning."
        };

        return
        [
            new PromptMessage
            {
                Role = Role.User,
                Content = new Content
                {
                    Type = "text",
                    Text = $"{systemInstruction}\n\n---\n\n{content}"
                }
            }
        ];
    }
}

